import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷五","description":"西溪易說 - 西溪易說卷五","frontmatter":{"title":"西溪易說卷五","description":"西溪易說 - 西溪易說卷五"},"headers":[],"relativePath":"classics/xixi/006.md","filePath":"classics/xixi/006.md"}'),i={name:"classics/xixi/006.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷五" tabindex="-1">西溪易說卷五 <a class="header-anchor" href="#西溪易說卷五" aria-label="Permalink to “西溪易說卷五”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷒ 兌下坤上</p><p>「臨」：</p><p>「臨」：元、亨、利、貞。至於八月有兇。彖曰：「臨」，剛浸而長，說而順，剛中而應，大亨以正，天之道也。至於「八月有兇」，消不久也。二陽生卦乃為「臨」。「臨」，君臨之道也。陽生於二，何以為君道也？當看乾卦二爻「見龍在田」，天下已有「利見大人」之意。蓋二雖非君位，君德已施普，而天下已文明，此二陽生，所以為君臨之道也。二爻曰「鹹臨」，君位在五，而感道已在二故也，故曰「臨：臨，元、亨、利、貞」。一陽生復，二陽生臨，「剛浸而長」也。德說而順，二剛得中，天下感應，陽道大亨而正，天運方來，理之必盛也。至於八月有兇，陰陽之道，消長不窮。二陽方生，聖人已為之戒，防患之早也。蓋二陽生臨，三陽生泰，四陽生壯，五陽生夬，六陽純乾，</p><p>一陰生姤，二陰生遁，三陰生否、四陰生觀。是八月也，二陽已消而在上矣。臨卦二陽生，方來之勢也；觀卦二陽消，已去之勢也。聖人於陽氣方生之時，預為陽氣已消之戒，故彖曰「消不久也」。聖人之慮遠矣。</p><p>象曰：澤上有地，「臨」；君子以教思無窮，容保民無疆。澤所以聚水也，澤水更有地，盡有可容處。臨下之道當以寬，王者必有容天下之量，故君子體臨之象，教思必無窮，保民必無疆也。「教思無窮」，體「兌」之「說」；「保民無疆」，體「坤」之「厚」。</p><p>初九，鹹臨，貞吉。象曰：「鹹臨貞吉」，志行正也。</p><p>初九一陽初生，已有感意。臨人之道，善意方萌，已感之矣。感人以善，臨之正也，故曰「鹹臨貞吉」，象曰云雲。</p><p>九二，鹹臨，吉，無不利。象曰：「鹹臨吉無不利」，未順命也。二陽生地上，天下文明矣，故曰「鹹臨吉無不利」，象曰「未順命也」。既曰「吉無不利」，何故「未順命」？蓋二陽方生，天下已感；五正君位，方能制命。順命在五，而感道在二，感人之道，當感之於未順命之先，猶之「乾為飛龍」，在五而二已利見也，故曰「未順命也」。</p><p>六三，甘臨，無攸利；既憂之，無咎。象曰：「甘臨」，位不當也；「既憂之」，咎不長也。</p><p>三居兌上，說體，「兌為口舌」，以甘言臨人者也，故「無攸利」。然三爻多憂，故言語不足以感人而危之，可「無咎」。象曰：「位不當也」，言所居不正也；「既憂之」，咎不長也。既憂其非，則得所以臨人之道矣，故「咎不長」。</p><p>六四，至臨，無咎。象曰：「至臨無咎」，位當也。</p><p>卦之至於八月有兇，數月至八，四陰生而二陽消，正此爻，故曰「至臨」。知患之至而能豫防之，臨道之善也，故「無咎」。象曰「位當也」，謂四陰之生，正當此位也。</p><p>六五，知臨，大君之宜，吉。象曰：「大君之宜」，行中之謂也。五君位，君道利明不利幽，故知臨為得宜。然臨人之道，必以寬簡，何至於用知？五純坤體，含弘光大之君也，故惟寬大之君，然後可以用知，否則苛察矣。故曰「知臨，大君之宜，吉」。言寬大之君，則宜用知而吉也。象曰：行中之謂也。言中則不至於過也。</p><p>上六：敦臨，吉，無咎。象曰：「敦臨」之吉，志在內也。</p><p>上六居坤之極，澤上有地，即此爻也，故曰「敦臨」。言其德厚無疆也，故「吉，無咎」。象曰「志在內也」，言志在保民，其中足以有容也。䷓ 坤下巽上</p><p>觀，</p><p>觀盥而不薦，有孚顒若。彖曰：大觀在上，順而巽，中正以觀天下。</p><p>「觀盥而不薦，有孚顒若」，下觀而化也。觀天之神道，而四時不忒。聖人以神道設教，而天下服矣。</p><p>二陽在上，為四陰所觀，天下觀化於上之象也。陽尊君位，以臨四陰，履順而巽，居中履正，以觀天下，故五為觀之主，大觀在上者也。四陰在下，觀化於下者也。在上則為君子之觀，在下則為小人之觀。君子，為人所觀者也；小人，觀於人者也。曰</p><p>「觀，盥而不薦，冇孚顒若」。顒，仰望也。下仰化於上，要以誠感人之薦鬼神也。當盥手而執匕鬯之時，誠意專一；至薦食之後，誠意少衰。故化人之道，當觀於方盥之時，而不觀於既薦之後也。天五方之民異性，而千里、百里不同風俗，然聖人設教，自有不疾而速、不行而至者。觀感之機，不待家喻而戶曉也。意誠於此而民孚於彼，要之，吾身自有本也。故曰：「觀天之神道，而四時不忒。」聖人以神道設教而天下服，是則大觀之君所為也。</p><p>象曰：風行地上，「觀」。先王以省方觀民設教。</p><p>風行地上，無遠近高下，莫不旁周而徧及。聖人所以為省方之禮，以觀民俗而設教化也。</p><p>初六：童觀，小人無咎，君子吝。象曰：「初六童觀」，小人道也。以柔居最下，去二陽遠，非能觀者，童子之觀也。卦以上體為觀之善，故君子處此則吝。小人，觀於人者也，其道固如此也。六二：𬮭觀，利女貞。象曰：「𬮭觀女貞」，亦可醜也。</p><p>以柔居內卦之中，處下體而不能上進，簾視壁聽，女子之觀也。</p><p>六三，觀我生，進退。象曰：「觀我生進退」，未失道也。</p><p>三處上體近，然未離乎下，進則為君子之觀，退則同小人之觀，但觀其所取也。象曰：未失道也。處下卦之上，去𬮭童觀為有間矣，進退尚未決，故「未失道」也。</p><p>六四，觀國之光，利用賓於王。象曰：「觀國之光」，尚賓也。四居群陰之上，進居上體而切近九五，諸侯賓於天子，觀光於上，國之象也。庭實旅百，奉之以玉帛，禮之至也。進得所觀而受殊禮也，處觀之善者也。</p><p>九五，觀我生，君子無咎。象曰：「觀我生」，觀民也。</p><p>五大觀在上，居中履正以觀天下，為觀之主，君子之觀也。一人之身，天下風俗之所繫，笑顰以下，皆觀感之樞機也，故不必觀化於天下，而常觀化於己，觀我生而無咎，則天下無咎矣。象曰：「觀我生」，觀民也。「觀我生」，乃所以觀民也，蓋君民無二本也。</p><p>上九：觀其生，君子無咎。象曰：「觀其生」，志未平也。</p><p>五觀我生矣，上又觀其生者，合己與物而觀之也，是亦君子之觀，故無咎。然以卦中六爻觀之，初六童觀，小人之觀也，非觀之善。二曰「𬮭觀」，女子之觀也，非觀之善。三曰進退去就，特未決也，亦非觀之善。己以賢德在上，為天下之觀，而下體皆未善，是天下未能觀化，道德未能一，風俗未能同也，故象曰「志未平也」。䷔ 震下離上 噬嗑，</p><p>噬嗑亨。利用獄。彖曰：頤中有物，曰「噬嗑」。噬嗑而亨，剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，「利用獄」也。</p><p>「噬」，齧也。「嗑」，合也。彖謂「頤中有物，曰噬嗑」。頤中四陰，上下二陽，如人之頤頷焉。今「噬嗑」九四，一陽梗其中，是頤中為物所梗。「頤中有物」，必噬而嗑之，乃亨通也，故卦名「噬嗑」。震下離上：震為雷，離為電。天地生萬物，有為造化之梗者，必用雷電以擊摶之。聖人之治天下，有為萬民之梗者，必用刑獄以斷制之。故「噬嗑」所以去頤中之梗者，雷電所以去天地之梗，刑獄所以去天下之梗也。卦辭曰「利用獄」，言有小人為天下之梗者，宜用刑獄以去之也。六爻只言用獄之道。彖：頤中有物曰「噬嗑」。「噬嗑」而亨，言噬而「嗑」，乃「亨」也。剛柔分六爻，剛與柔等也。「動而明」，震體動而離體明也。「雷電合而章」。雷之擊物，必與電合，然後成章也。人之頤中，自有雷電，齒剛而舌柔，雷之擊摶，必與電合；齒之噬嗑，必與舌俱，然後成章也。「柔得中而上行」。謂六五得中而居上，以柔居五，雖不當位，然後得治獄之道也。蓋聖人用刑，出不得已，以柔治獄，聖人之仁也。此義見在五爻。</p><p>象曰：「雷電」，「噬嗑」。先王以明罰勑法。</p><p>天地去萬物之梗，必以雷電，猶去頤中之梗，必以「噬嗑」。先王體之，有小人之梗，必用刑獄，故體「離」之照以明罰，體「震」之威以勑法。</p><p>初九，屨校滅趾，無咎。象曰：「屨校滅趾」，不行也。</p><p>六爻皆說用獄，初為惡之始，上為惡之終，中四爻同頤中之物，六爻節目如此。初最下，小人之為惡者也，為惡之始，姑少懲之，以屨校而滅其趾，令不得行而聽其改過也，故因「滅趾」而「無咎」。周禮：「坐之圜土，納之嘉石」，乃其義也。繫辭曰：「小人不恥不仁，不畏不義，不見利不勸，不威不懲。」小懲而大誡，此小人之福也。易曰：「屨校滅趾，無咎。」</p><p>六二，噬膚滅鼻，無咎。象曰：「噬膚滅鼻」，乘剛也。</p><p>以六爻之位言之，五，君位也，為治獄之主；四，大臣位也，為治獄之卿；又其下也，為治獄之吏。頤中之物最大，乾胏是乾胏，乾肉之冇骨者，最難噬也。六二體柔，以噬膚之道噬之，自傷其鼻，然亦「無咎」也。治獄者也，故咎不在己。象曰「乘剛也」，謂九四剛物也，己以柔道乘而噬也，故傷也。六三，噬臘肉，遇毒，小吝，無咎。象曰：「遇毒」，位不當也。六三體亦柔，見二之傷也，以噬臘肉之道噬之，亦遇其毒，蓋不虞乾胏之有骨也，遂為所毒，雖小吝，亦無咎，意在去惡己，則何咎！象曰「位不當也」，以三體柔也。</p><p>九四，噬乾胏，得金矢，利艱貞，吉。象曰：「利艱貞吉」，未光也。頤中之梗，正在此爻。九四近君，治獄之卿也。諸爻以柔噬，九四獨以剛噬。「乾胏」，乾肉之有骨者。此小人難噬，正如「乾胏」。而九四體剛，以噬乾胏之道噬之，遂得其情，故曰「噬乾胏，得金矢」。古者司寇以兩劑禁民獄，入鉤金，然後聽之，既得其情，則得鉤金；以兩造禁民訟，入束矢，然後聽之，既得其情，則得束矢。曰「得金矢」，謂得其情也。然不敢以為能也，宜以「艱貞」之道自守，則「吉」。象曰「未光也」，蓋刑期於無刑，治獄者之職也。今猶有小人之梗，非治獄之善也。古人治獄如得其情，則哀矜而勿喜，蓋謂此也。</p><p>六五：噬乾肉，得黃金，貞厲，無咎。象曰：「貞厲無咎」，得當也。六五君位，所謂「柔得中而上行」者也。九四「噬嗑」，既得其情矣，以獄之成告於六五。五，柔主也，依前以噬乾肉之道噬之。「乾肉」，無骨者也，蓋以柔噬之也。於是不忍用刑者曰「得黃金」，用贖刑也。古者金作贖刑，如呂刑五刑之贖皆有罰，以千鍰為差是也。九四以剛噬，六五以柔噬。以剛噬者，冇司執法之公；以柔噬者，人君不忍之仁也。然猶貞厲則無咎。貞厲，謹懼也。正如穆王訓夏贖刑，刑既輕矣，猶曰「朕言多懼」是也。象曰「得當也」，言以柔用獄，得用獄之當也者，得聖人一個慈祥惻怛之心，更無窮也。</p><p>上九：何校滅耳，兇。象曰：「何校滅耳」，聰不明也。</p><p>九處卦之終，小人為惡之大者也，故滅其耳。繫辭曰：善不積不足以成名，惡不積不足以滅身。小人以小善為無益而弗為也，以小惡為無傷而弗去也，故惡積而不可掩，罪大而不可解。易曰：「何校滅耳，兇。」䷕ 離下艮上</p><p>賁賁：亨，小利有攸往。彖曰：「賁，亨」，柔來而文剛，故「亨」。分剛上而文柔，故「小利有攸往」，天文也。文明以止，人文也。觀乎「天文」，以察時變；觀乎「人文」，以化成天下。</p><p>賁，飾也。以文為飾，物相合則必有文。人道無本不立，無文不行。君臣之交，賓主之歡，父子兄弟、夫婦之好，皆當有文以相接。禮儀三百，威儀三千，非徒為是繁縟，有本者固如是也。卦自泰變，陰陽往來，交錯而成文，曰：「賁，亨，小利有攸往。」止得從彖解曰：柔來而文剛，故亨。上體本坤，上六一柔下來文二成離，離為文明，故亨。下體本乾，九二以剛往而文上成艮。艮，止也，故「小利有攸往」。剛柔往來，交錯成文，此天文也。如日月之晝夜，陰陽之寒暑，百穀草木之榮椹，皆相錯而後成文，此自然之文也，故曰「天文」。以六爻之象言也。以人道言之，則離義取明，艮義取止。文明以止，人文也。六爻之義，上下貴相文。五居君位，以上文下，吉而有喜，是文明以亨也。初二、三四，臣位也，以下文上，則不可遽進，文明以止也，「小利有攸往」之義也。此人事，故曰「人文」也。賁亨屬五爻，「小利有攸往」屬下四爻。蓋君以禮遇臣，君臣會遇，無往不亨。士之在下，自文其身，以待上求，非其禮物之至，則不輕售，安可以驟進哉？皆不往而止，以上來成離、下往成艮為義也。曰：觀乎「天文」，以察時變；觀乎「人文」，以化成天下。日月星辰，往來運行，天文也，而時變系焉。君臣、父子、夫婦、朋友相接之禮，人文也，而教化系焉。人文既備，則天下化成矣。</p><p>象曰：山下有火，賁，君子以明庶政，無敢折獄。</p><p>山下有火，野燒之火也。焚薙榛棘，然後草木敷暢，物得其賁，所以為文。君子體此以明庶政，無敢折獄，禮樂明備，百度修舉，所以飾國也。獄貴情實，無所用文，故不敢以文折獄。</p><p>初九，賁其趾，舍車而徒。象曰：「舍車而徒」，義弗乘也。下四爻皆取自文其身，不遽往為義。初居最下，趾之象也。趾所以行，自賁其所行也。所樂在我，無用乘人之車也，故寧舍之而徒也。象曰「義弗乘也」，以義為重，前車後乘，繋馬千駟，不足貴也。</p><p>六二，賁其須。象曰：「賁其須」，與上興也。</p><p>二居中，離體文明，道德積中，達於面目，所謂仁義禮智根於心，其生色粹然見於面者也。其所賁，與初爻賁其一體者異矣。象曰「與上興也」，言五自上而求賁，則可與興起，然不先往也。九三，賁如濡如，永貞吉。象曰：「永貞」之「吉」，終莫之陵也。濡，潤澤也。文明之極，其德之盛，足以潤其身也，故「賁如」又「濡如」，清明在躬，志氣如神者也。又與「賁其須」者異矣，然亦未可進也，故曰「永貞吉」。象曰「終莫之陵也」，言終當大用也。</p><p>六四，賁如皤如，自馬翰如，匪寇婚媾。象曰：六四當位疑也；「匪寇婚媾」，終無尤也。</p><p>四在三上，賁盛於三，蓄德老成，可為典型者也，故曰「賁如皤如，華髮黃耇」之象也。「自馬翰如」，其馬亦潔白班翰而不進，不輕屈於人，所謂「皎皎白駒，在彼空谷」者也。「匪寇婚媾」，非禮而來，皆寇我者之人也，安可以寇得哉！婚媾則往矣，言備禮也。正如黃綺諸公，不肯為嫚罵，折及呂澤之聘幣，至羽翼翻然而起矣。蓋自「賁其趾」以至「蓄德老成」，是惟無用，用則邦家有光矣。然六五束帛已「戔戔」然而來，天下將被潤澤矣。象曰「當位疑也」，言不輕往也；曰「終無尤也」，言出處之節，無一毫瑕尤也。</p><p>六五，賁於丘園，束帛戔戔，吝，終吉。象曰：六五之「吉」，有喜也。</p><p>有老成之人在下，而五欲求之，必得所以賁之之道。禮物不可輕也，故「束帛戔戔」然至於「丘園」之下，將庶幾其賁我乎？上下相賁，文明而亨，此其時也。雖然，我何以聘幣為哉？三至然後翻然，故始未免吝，終則吉。象曰：六五之「吉」，冇喜也。其肯來賁，喜可知也。上九：白賁，無咎。象曰：「白賁無咎」，上得志也。</p><p>至五爻相賁，文之極也。物極則反，故上九處賁之極，又反而歸於「白賁」，以質為貴也。所謂「甘受和，白受採，繪事後素」是也。曰「白賁」者，所以反禮之本者也。象曰「上得志也」，謂得其本然之志也。易道履貴素履，賁尚「白賁」，皆貴質之義。</p><p>又說：上九處卦之上而無位，剛上而止，自潔其身，非六五束帛之能賁也。箕潁之流，煙霞泉石，自是一種人物，是以白為賁者也。有道之世，如是白賁者多矣。象曰：「上得志也」，得遂其素志也。䷖ 坤下艮上</p><p>剝</p><p>剝：不利有攸往。彖曰：「剝」，剝也，柔變剛也。「不利有攸往」，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。陰陽消長，天之理也。一陰生姤，積而至五，陽將盡矣。其卦為剝，五陰剝一陽，眾小人剝君子之象也。雖然，剝不盡則不復，碩果不食，生意已在其中矣，此天運之所以不窮也。曰「不利有攸往」，君子處剝，不宜往也。彖曰：「剝」，剝也，柔變剛也。五柔變一剛也。「不利有攸往」，小人長也。小人長，君子當順受也。順而止之，觀象也。坤體順，艮體止。順而止之，處小人之道也。自古小人之禍，皆成於君子之爭，蓋爭則小人必勝也。君子尚消息盈虛，天行也。「消息盈虛」，天運之自然也。有善必有惡，有君子必有小人，其天地陰陽之數歟！</p><p>象曰：山附於地，「剝」。上以厚下安宅。山夷而附於地，剝象也。然山雖夷，其下愈厚，其土依然在也。小人之剝，法度壞亂。君子德澤猶在，人心未泯，民心不搖，則天道可回矣。厚下安宅，所以固人心也。</p><p>初六，剝床以足，蔑貞兇。象曰：「剝床以足」，以滅下也。自下剝上，君子在上處床也，小人自下剝之，漸而毀也。初且剝足，意在蔑正也。象曰：以蔑下也。</p><p>六二，剝床以辨，蔑貞兇。象曰：「剝床以辨」，未有與也。二陰生剝至辨也，亦蔑貞兇。象曰：「未有與也」，言黨猶未盛，且剝辨也。</p><p>六三，剝之無咎。象曰：「剝之無咎」，失上下也。</p><p>聖人未嘗不開小人為善之門，一陽在上，君子也；三與上正應己，小人也。處群小人之中，自異而應上，聖人許之曰「剝之無咎」。象曰「失上下也」，言失上下四陰而應上九也。</p><p>六四，剝床以膚，兇。象曰：「剝床以膚」，切近災也。</p><p>四陰生床，剝盡而及膚矣，是君子之身已被其傷矣，故曰「切近災也」。不言「蔑貞」者，蓋四陰生，小人之道已盛，而為君子者猶不能見幾而去，則非蔑貞之罪也。</p><p>六五，貫魚，以宮人寵，無不利。象曰：「以宮人寵」，終無尤也。五陰在下，牽連而進，如貫魚然。自古小人之亂，皆由人主委以大兵大權，故其勢得以害君子。若以閹人掃除之職主之，則無不宜矣。五為君位，故言所以待小人之道。</p><p>上九，碩果不食，君子得輿，小人剝廬。象曰：「君子得輿」，民所載也。「小人剝廬」，終不可用也。</p><p>剝而至此，陽將盡矣，剝盡則復陽未嘗絕也。人之食果，以漸而剝，必留一碩大者不剝，其所以不剝而食者，留以為種子。此大者剝下，生意已存於不食之中，故剝卦賴乎此陽，剝盡遂反為復，以喻君子之不可盡剝也。君子得輿，小人剝廬：在下而載其上，小人之事。一陽在上，眾陰自下載之，有「君子得輿」之象。廬居上而庇其下，君子之事，一陽在上，而眾陰自下剝之，有「小人剝廬」之象。初剝床之足，剝之不已，則剝其辨。又剝之不已，則剝其膚。至剝之極，則剝及於廬，是自剝其廬也。蓋一君子在上，小人猶得所庇；君子盡去，則小人無託身之所矣。象曰：「君子得輿」，民所載也。「小人剝廬」，終不可用也。蓋小人極盛，然後君子為民所屬望；禍亂既極，然後知小人之不可用也。䷗ 震下坤上</p><p>復，</p><p>復，亨。出入無疾，朋來無咎。反覆其道，七日來複，利有攸往。彖曰：「復，亨」。剛反。動而以順行，是以「出入無疾，朋來無咎」。「反覆其道，七日來複」，天行也。「利有攸往」，剛長也。復，其見天地之心乎？</p><p>序卦：「物不可以終盡，剝窮上反下，故受之以復。」物無剝盡之理，故剝極則復來，陰極則陽生。陽剝於上而復生於下，窮上而反下也。卦，一陽生五陰之下，陰極而陽復也。陽，君子之道。陽消極而復反；君子之道，消極而復長也，故為反善之義。曰「復，亨」，陽道長矣，是以「亨」也。陽長而出，陰消而入，順消息盈虛之理，無相疾害。一陽方動，眾陽從之，以類而升，何咎之有？「反覆其道，七日來複」。謂消長之道，反覆迭至。陽之消，至七日而來複。姤，陽之始消者也，七變而成復，故云七日，謂七更也。陽進則陰退，君子道長，小人道消，故「利有攸往」。彖：剛反，動而以順行。陽反於下，下體為震，震，動也。上體為坤，坤，順也。陽動於下，上體皆坤，以順而長也，是以無疾。曰「七日來複，天行也。」蓋陰陽消長，天運自然也。曰：利有攸往，剛長也。一陽來複，以漸而長，是君子道長也。復，其見天地之心乎？一陽生於下，乃天地生物之心也。夫窮冬積陰之時，天地幾於無生意矣，而陽氣已動於黃泉之下，猶之人焉，方其物慾之深也，幾於無天理矣，而性善之端，要不可泯也，必有時而發。就其發處而觀之，則天地之心見矣。程氏曰：「先儒以靜見天地之心，蓋不知動乃見天地之心，非知道者，孰能識之？」象曰：雷在地中，復。先王以至日閉關，商旅不行，後不省方。</p><p>陽氣相搏而成雷，雷以十月閉蟄，十一月一陽生。陽氣已動於地下，是雷已動而未發。雷動於地，陽復於下之象也。雷動於冬而春發聲，陽復於冬而春發生，雖其氣尚微，「先王以至日閉關，商旅不行，後不省方」，恐其踐履陽氣也。聖人輔相天地之道也。</p><p>初九，不遠復，無祗悔，元吉。象曰：「不遠」之復，以修身也。一陽在下，天地之心，性善之端也，故六爻以復善為義。初，復之始，始而知復，知善未遠，不遠復也，故不至悔而元吉。象曰：「以修身也」，學者宜以此修身也。繫辭曰：「君子知微知彰，萬夫之望。」子曰：「顏氏之子，其殆庶幾乎！有不善未嘗不知，知之未嘗復行也。」易曰：「不遠復，無祗悔，元吉。」</p><p>六二，休復，吉。象曰：「休復」之吉，以下仁也。</p><p>休，善也。二取初近，從善而復也，故「吉」。象曰「以下仁也」，「仁」，人心也。善端之發，莫切於仁，初復於仁而二下之也。</p><p>六三：頻復，厲無咎。象曰：「頻復」之厲，義「無咎」也。</p><p>三不正而位危，又取初遠，屢失而屢復也。屢失故厲，屢復故「無咎」，過而復之也。</p><p>六四：中行獨復。象曰：「中行獨復」，以從道也。</p><p>四處五陰之中，取初雖遠，而獨與初應，以道自復者也。初曰「以修身」，二曰「以下仁」，四曰「以從道」，蓋修身以道，修身以仁，無二理也。</p><p>六五：敦復，無悔。象曰：「敦復無悔」，中以自考也。</p><p>五居上體純坤，天性之至厚者也。雖取初遠而以性復中以自考，言反求於己，不因人而復也。</p><p>上六：迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵。象曰：「迷復」之兇，反君道也。</p><p>上取初遠，物慾之深，迷而不知復者也。妄動固有災眚，好大喜功，敗而不悟，至於十年不克徵，其秦皇、漢武之所為乎？故象曰：「反君道也。」䷘ 震下乾上 無妄，</p><p>無妄：元亨，利、貞。其匪正有眚，不利有攸往。彖曰：無妄，剛自外來而為主於內。動而健，剛中而應，大亨以正，天之命也。「其匪正有眚，不利有攸往」，「無妄」之往，何之矣？天命不祐，行矣哉？</p><p>程氏曰：無妄，序卦：復則不妄矣，故受之以無妄。復者，反於道也。既復於道，則合於正理而無妄，故復之後受之以無妄也。為卦乾上震下。震，動也。動以天為無妄，動以人慾則妄矣。「無妄」，聖人可也。學者未敢言無妄，且自不妄入也。故由不妄以至無妄，所謂自明而誠也。如司馬溫公教學者以誠，又未敢言無妄，且自不妄語入，是又略下教人也。曰：無妄，元亨、利、貞，大亨以正，無妄之理也。初、二、四、五爻得之。其匪正有眚，不利有攸往。其處不正則妄矣，故有災眚，而「不利有攸往」。三與上當之。彖曰：剛自外來而為主於內。一陽自卦之外來，居內卦之下，變坤為震，遂成無妄。蓋無妄，實理也。天地人同就太虛中稟得，天地得之以為天，地人得之以為人，非有附麗而來也。與他卦之變不同，故曰「自外來」。故初爻為無妄之主，而六爻惟初得「吉」。蓋初動之始，無一毫私意，全「無妄」之體者也。動而健，剛中而應，震動而乾健，五剛得中，二陰又得中而相應，無妄之義也。大亨以正，天之命也。無妄，誠也。誠者，天之道也。元亨利貞，天德之全也。無妄則與天為一，而天德純全，故曰「天之命」也。子思於中庸首篇便曰：「天命之謂性。」蓋本諸此。其匪正有眚，不利有攸往。無妄之往，何之矣？天命不祐，行矣哉！此釋上卦辭也。言無妄之往，何往而不可？若有眚，則天命不祐，何行哉？言有眚則「不利有攸往」也。</p><p>象曰：天下雷行，物與無妄；先王以茂對時，育萬物。天下雷行，萬物肅然而聽命，其心至一也。天與萬物未嘗相誤，故曰「物與無妄」。聖人充此心，勿忘勿助，茂對時，育萬物，全是順天理。</p><p>初九，無妄，往吉。象曰：「無妄」之往，得志也。</p><p>一陽自外來，居無妄之初，成卦由之，動以應乾，其動以天，無妄之至也，故「往吉」，象曰「得志也」。以理而動，無往不可，其心泰然矣。</p><p>六二，不耕穫，不菑畬，則利有攸往。象曰：「不耕穫」，未富也。無妄，誠也，實理也，盡人物之性於己也，有一毫求得於外心，便害無妄之體。耕而獲菑畬，求得於外也，必無耕穫菑畬之心，然後可以有所往。二以陰居陰，雖得中，然未實也。中未實則必外求，因有此戒，故象曰「未富也」。樊遲之學稼，許子之並耕，皆耕穫菑畬者也。</p><p>六三，無妄之災，或繋之牛，行人之得，邑人之災。象曰：「行人」得牛，邑人災也。</p><p>以六居三，其位不正，處動之極，動而得災。然無妄得災，非己致也。不言悔吝，蓋無妄而災眚至，皆吾進德之驗也。有一毫咎人之心，則妄矣。九四：可貞，無咎。象曰：「可貞，無咎」，固有之也。</p><p>九四，心位也。鹹卦可見本然之心，無一毫之妄也。存得本然之心，則天理見矣，故曰「可貞，無咎」，言此心可貞，守之而「無咎」也。象曰「固有之也」，言此心固有，非外鑠我也。</p><p>九五：無妄之疾，勿藥有喜。象曰：無妄之藥，不可試也。五居乾體而得中，純乎天理，而與天為一者也，必至此而後可以言命。「無妄」不宜疾也，而得疾則天也，故可以勿藥而有喜。如子疾病，子路請禱，子曰：「丘之禱久矣。」伯牛有疾，子曰：「亡之，命矣夫！」如夫子、伯牛之得疾，然後謂之「無妄之疾」。聖賢平時陟降，無非對越上帝時也，疾何用禱哉？妄而得疾，藥亦無及矣。故象曰：「無妄之藥，不可試也。」</p><p>上九：無妄，行有眚，無攸利。象曰：「無妄」之「行」，窮之災也。處卦之終，其位不正，所謂匪正有眚者也。西溪易說卷五。</p>',97)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
